//! The dictionary of the data operations and analyses (app request 16, L088): `operation_table`, generated by
//! `ecosystem/tools/build.py` from `ecosystem/data/operations.yml`, against the core.
//! - the generated table holds exactly the ids and keys of the YAML, in its order (build.py was run);
//! - its operations are exactly those the control file accepts (`Operation::from_table`), and their settings' keys
//!   exactly the keys it reads for each (another key is refused); its analyses are the functions of `data_ops`;
//! - every setting says its name, unit, meaning, range, default and how a value is proposed;
//! - the defaults it states are the code's (`data_ops::DEFAULT_*`, GSAS-II's λ for N points).

use drs::control::syntax;
use drs::data_ops::{self, Operation};
use drs::operation_table::OPERATIONS;
use std::path::Path;

fn table(text: &str) -> syntax::Table {
    let doc = syntax::parse(text);
    assert!(!doc.has_errors(), "{text}: {:?}", doc.diagnostics);
    doc.tables.into_iter().find(|t| t.header.is_some()).unwrap()
}

/// Whether the control file reads `op` as an operation (an error other than "is not an operation" means it does).
fn accepted(op: &str) -> bool {
    match Operation::from_table(&table(&format!("[[pattern.operation]]\nop = \"{op}\"\n"))) {
        Ok(_) => true,
        Err(d) => !d.message.contains("is not an operation"),
    }
}

#[test]
fn operation_dictionary() {
    let yml = std::fs::read_to_string(Path::new(env!("CARGO_MANIFEST_DIR")).join("../ecosystem/data/operations.yml")).unwrap();
    let ids: Vec<&str> = yml.lines().filter_map(|l| l.strip_prefix("  - id: ")).map(str::trim).collect();
    assert_eq!(ids, OPERATIONS.iter().map(|o| o.id).collect::<Vec<_>>(), "operation_table is not the YAML's (run build.py)");
    let keys: Vec<&str> = yml.lines().filter_map(|l| l.strip_prefix("      - key: ")).map(str::trim).collect();
    assert_eq!(keys, OPERATIONS.iter().flat_map(|o| o.settings.iter().map(|s| s.key)).collect::<Vec<_>>(), "settings differ from the YAML's");

    // The operations: those the control file accepts, and no other.
    let ops: Vec<&str> = OPERATIONS.iter().filter(|o| o.kind == "operation").map(|o| o.id).collect();
    for op in &ops {
        assert!(accepted(op), "{op}: in the dictionary, not accepted by the control file");
    }
    for word in ["mask", "delete", "smooth", "rebin", "normalize", "add", "subtract", "merge", "convert", "wavelength", "crop", "scale", "shift"] {
        assert_eq!(accepted(word), ops.contains(&word), "{word}: accepted by the control file and described in the dictionary must agree");
    }
    // Each operation's settings are the keys the control file reads for it: every one accepted (with the others an
    // operation takes, a typical value), and a key of another operation's refused as unknown when not read at all.
    let value = |k: &str| match k {
        "from" => "10.0", "to" => "20.0", "points" => "5", "order" => "2", "factor" => "2", "step" => "0.02", "mode" => "\"sum\"",
        "by" => "\"factor\"", "file" => "\"other.xye\"", "reader" => "\"xye\"", "scale" => "1.5", "wavelength" => "1.5406",
        _ => panic!("{k}"),
    };
    let all: Vec<&str> = OPERATIONS.iter().filter(|o| o.kind == "operation").flat_map(|o| o.settings.iter().map(|s| s.key)).collect();
    for o in OPERATIONS.iter().filter(|o| o.kind == "operation") {
        for s in o.settings {
            let v = match (o.id, s.key) {
                ("convert", "to") => "\"d\"",
                ("wavelength", "to") | ("normalize", "to") => "1.0",
                ("mask" | "delete", "points") => "[10.0, 10.5]",
                (_, k) => value(k),
            };
            let t = table(&format!("[[pattern.operation]]\nop = \"{}\"\n{} = {v}\n", o.id, s.key));
            if let Err(d) = Operation::from_table(&t) {
                assert!(!d.message.contains("is not a key"), "{}: {} not read: {}", o.id, s.key, d.message);
            }
        }
    }
    let known = ["from", "to", "points", "order", "factor", "step", "mode", "by", "file", "reader", "scale", "wavelength"];
    let mut described: Vec<&str> = all.clone();
    described.sort_unstable();
    described.dedup();
    let mut k2 = known.to_vec();
    k2.sort_unstable();
    assert_eq!(described, k2, "the keys the dictionary describes and the keys the control file reads");
    // Each operation reads exactly its settings' keys: the parser's list is the dictionary's, and any other key refused.
    for o in OPERATIONS.iter().filter(|o| o.kind == "operation") {
        assert_eq!(data_ops::keys_of(o.id).unwrap(), o.settings.iter().map(|s| s.key).collect::<Vec<_>>().as_slice(), "{}", o.id);
        for k in known.iter().filter(|k| !o.settings.iter().any(|s| s.key == **k)) {
            let t = table(&format!("[[pattern.operation]]\nop = \"{}\"\n{k} = 1\n", o.id));
            let e = Operation::from_table(&t).unwrap_err().message;
            assert!(e.contains(&format!("\"{k}\" is not a key of {}", o.id)), "{}: {k}: {e}", o.id);
        }
    }
    // An unknown key is refused, so the list above is the parser's.
    let t = table("[[pattern.operation]]\nop = \"mask\"\nwidth = 3\n");
    assert!(Operation::from_table(&t).unwrap_err().message.contains("is not a key"));

    // The analyses are data_ops' functions.
    let analyses: Vec<&str> = OPERATIONS.iter().filter(|o| o.kind == "analysis").map(|o| o.id).collect();
    assert_eq!(analyses, ["peak_search", "auto_background"]);
    for o in OPERATIONS {
        assert!(data_ops::settings(o.id).is_some());
        assert!(!o.name.is_empty() && !o.meaning.is_empty() && !o.sigma.is_empty() && !o.source.is_empty(), "{}", o.id);
        for s in o.settings {
            for (what, v) in [("name", s.name), ("unit", s.unit), ("meaning", s.meaning), ("range", s.range), ("default", s.default), ("proposed", s.proposed)] {
                assert!(!v.trim().is_empty(), "{}.{}: no {what}", o.id, s.key);
            }
        }
    }

    // The defaults are the code's.
    let default = |op: &str, key: &str| data_ops::settings(op).unwrap().settings.iter().find(|s| s.key == key).unwrap().default;
    assert_eq!(default("peak_search", "min_prominence").parse::<f64>().unwrap(), data_ops::DEFAULT_MIN_PROMINENCE);
    assert_eq!(default("peak_search", "min_significance").parse::<f64>().unwrap(), data_ops::DEFAULT_MIN_SIGNIFICANCE);
    assert_eq!(default("auto_background", "max_iter").parse::<usize>().unwrap(), data_ops::DEFAULT_MAX_ITER);
    for op in ["add", "subtract", "merge"] {
        assert_eq!(default(op, "scale").parse::<f64>().unwrap(), data_ops::DEFAULT_SCALE);
    }
    assert_eq!(default("rebin", "mode"), "sum");
    assert_eq!(data_ops::DEFAULT_REBIN_MODE, data_ops::RebinMode::Sum);
    // GSAS-II's λ for N points, as the dictionary writes it: min(10, (int(10·log₁₀(N)^1.5) − 9.5)/10).
    assert!(default("auto_background", "log_lambda").contains("min(10, (int(10·log₁₀(N)^1.5) − 9.5)/10)"));
    for n in [100usize, 2510, 13091, 100000] {
        let want = (((10.0 * (n as f64).log10().powf(1.5)).floor() - 9.5) / 10.0).min(10.0);
        assert_eq!(data_ops::default_log_lambda(n), want, "N = {n}");
    }
    println!("{} operations and {} analyses, {} settings described", ops.len(), analyses.len(), OPERATIONS.iter().map(|o| o.settings.len()).sum::<usize>());
}
